//! Engine codes per model generation and the target values that follow
//! from them (warm idle speed, coolant temperature).
//!
//! The codes come from the technical data tables of the Wikipedia article of
//! each generation (data/engines/engines.csv, CC BY-SA 4.0, generated by
//! tools/gen_engines.py), split into petrol and diesel engines.
//!
//! Target values. Idle speed is a band per fuel, the range warm engines of
//! these years idle in without load: no free source gives the exact idle
//! speed of each engine, so Caruspex does not pretend to know it. Engine
//! specific is the coolant: engines with a map-controlled thermostat
//! (Kennfeldthermostat) run hotter at part load on purpose, so the warning for
//! very hot coolant comes later for them. Listed are only the families whose
//! Wikipedia article says so (BMW N52).

use crate::catalog::VehicleGeneration;
use crate::generated::engines::ENGINES;

/// One generation of the generated table.
pub struct EngineRow {
    pub brand: &'static str,
    pub model: &'static str,
    pub generation: &'static str,
    pub petrol: &'static [&'static str],
    pub diesel: &'static [&'static str],
    /// The Wikipedia article and revision the codes come from.
    pub source: &'static str,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum EngineFuel {
    Petrol,
    Diesel,
}

/// Target values for one engine.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EngineTargets {
    /// Warm idle speed without load, 1/min.
    pub idle_min: f64,
    pub idle_max: f64,
    /// From here the coolant counts as very hot, °C.
    pub coolant_hot: f64,
    /// The engine has a map-controlled thermostat.
    pub map_thermostat: bool,
}

/// The general limit for very hot coolant (as the health check uses it).
pub const COOLANT_HOT: f64 = 108.0;
/// For engines with a map-controlled thermostat, which may run about 105 to
/// 110 °C at part load.
pub const COOLANT_HOT_MAP: f64 = 113.0;

/// Engine families with a map-controlled thermostat, by code prefix, each
/// with the article that says so.
const MAP_THERMOSTAT: &[(&str, &str)] = &[("N52", "https://de.wikipedia.org/wiki/BMW_N52")];

/// The engine codes of a generation, if the table has them.
pub fn engines_for(g: &VehicleGeneration) -> Option<&'static EngineRow> {
    ENGINES
        .iter()
        .find(|e| e.brand == g.brand && e.model == g.model && e.generation == g.generation)
}

/// All rows of the table.
pub fn engine_rows() -> &'static [EngineRow] {
    ENGINES
}

/// Codes of a generation with their fuel, petrol first.
pub fn engine_codes(g: &VehicleGeneration) -> Vec<(&'static str, EngineFuel)> {
    let Some(e) = engines_for(g) else {
        return Vec::new();
    };
    e.petrol
        .iter()
        .map(|c| (*c, EngineFuel::Petrol))
        .chain(e.diesel.iter().map(|c| (*c, EngineFuel::Diesel)))
        .collect()
}

/// Whether the engine has a map-controlled thermostat.
pub fn map_thermostat(code: &str) -> bool {
    MAP_THERMOSTAT
        .iter()
        .any(|(prefix, _)| code.starts_with(prefix))
}

/// Target values of one engine.
pub fn targets_for_code(code: &str, fuel: EngineFuel) -> EngineTargets {
    let (idle_min, idle_max) = match fuel {
        EngineFuel::Petrol => (600.0, 950.0),
        EngineFuel::Diesel => (650.0, 950.0),
    };
    let map = map_thermostat(code);
    EngineTargets {
        idle_min,
        idle_max,
        coolant_hot: if map { COOLANT_HOT_MAP } else { COOLANT_HOT },
        map_thermostat: map,
    }
}

/// The target values for a car of this generation, when every engine that
/// fits (all, or those of the given fuel) has the same ones; with the codes
/// they hold for ("N52B25 N52B30"). `None` without engine codes or when the
/// engines differ and the fuel does not tell them apart.
pub fn targets_for(
    g: &VehicleGeneration,
    fuel: Option<EngineFuel>,
) -> Option<(EngineTargets, Vec<&'static str>)> {
    let codes: Vec<(&'static str, EngineFuel)> = engine_codes(g)
        .into_iter()
        .filter(|(_, f)| fuel.is_none_or(|want| *f == want))
        .collect();
    let (first_code, first_fuel) = *codes.first()?;
    let first = targets_for_code(first_code, first_fuel);
    codes
        .iter()
        .all(|(c, f)| targets_for_code(c, *f) == first)
        .then(|| (first, codes.iter().map(|(c, _)| *c).collect()))
}

/// Codes for a line of text: up to four, then how many more.
pub fn codes_text(codes: &[&str]) -> String {
    let mut out = codes.iter().take(4).copied().collect::<Vec<_>>().join(" ");
    if codes.len() > 4 {
        out.push_str(&format!(" +{}", codes.len() - 4));
    }
    out
}
